package arrayd;

public class ManualArray {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int[] number_array = {12,3,4,54,32,55,38,78,99};
		
		for (int num : number_array) {  // We can give any name in the place of num (which is iterator)
			System.out.println(num);
		}

	}

}
